class Translator:
    """Singleton-ish translator with change listeners for runtime switching."""

    def __init__(self, lang: str = "en"):
        self.lang = lang if lang in dict(LANGUAGES) else "en"
        self._listeners = []

    def set_language(self, lang: str):
        if lang in dict(LANGUAGES) and lang != self.lang:
            self.lang = lang
            for cb in list(self._listeners):
                cb()

    def connect_changed(self, callback):
        self._listeners.append(callback)

    def disconnect_changed(self, callback):
        if callback in self._listeners:
            self._listeners.remove(callback)

    def __call__(self, key: str, **kwargs) -> str:
        entry = _S.get(key)
        if not entry:
            return key
        text = entry.get(self.lang) or entry.get("en") or key
        if kwargs:
            try:
                text = text.format(**kwargs)
            except (KeyError, IndexError):
                pass
        return text


def system_language() -> str:
    """The desktop's own language, if Petacore speaks it, else English.

    Used only before the person has chosen: the very first screen asks them
    to pick a language, and it should ask in one they can read.
    """
    import os
    for variable in ("LANGUAGE", "LC_ALL", "LC_MESSAGES", "LANG"):
        value = os.environ.get(variable, "")
        for part in value.split(":"):             # LANGUAGE may list several
            code = part.split(".")[0].split("@")[0].split("_")[0].lower()
            if code in dict(LANGUAGES):
                return code
    return "en"


def start_language(config) -> str:
    """The saved choice, or — on the very first start — the desktop's."""
    if config.get("first_run"):
        return system_language()
    return config.get("language")


translator = Translator()
